using System;using System.IO;using System.Collections.Generic;using UnityEngine;using UnityEditor;
public static class OpenRPGHouseSurfaceResourcesV613 {
 [Serializable]public class Item{public string guid,raw_output;}
 [Serializable]public class Request{public string output,shader_path;public Vector2[] uvs;public Item[] materials;}
 [Serializable]public class TextureRow{public string property,guid,format,graphics_format,filter,wrap_u,wrap_v;public int width,height,mips,aniso;}
 [Serializable]public class Row{public string guid,raw_output;public int output_bytes;public TextureRow[] textures;public bool source_material_unchanged;}
 [Serializable]public class Report{public string unity_version,graphics_api,gpu,color_space;public int cases,rows;public Row[] materials;public bool source_materials_unchanged,full_import=false,complete_surface_verified=false;}
 static string Guid(UnityEngine.Object o){string g;long i;if(!AssetDatabase.TryGetGUIDAndLocalFileIdentifier(o,out g,out i))throw new Exception("Identity missing");return g;}
 public static void Export(){
  var args=Environment.GetCommandLineArgs();int i=Array.IndexOf(args,"--openrpg-manifest");if(i<0)throw new Exception("Manifest absent");var r=JsonUtility.FromJson<Request>(File.ReadAllText(args[i+1]));if(File.Exists(r.output))throw new Exception("Preserve evidence");var shader=AssetDatabase.LoadAssetAtPath<Shader>(r.shader_path);if(shader==null||!shader.isSupported)throw new Exception("Probe shader unavailable");var result=new List<Row>();
  var inputs=new Texture2D(r.uvs.Length,1,TextureFormat.RGBAFloat,false,true);var colors=new Color[r.uvs.Length];for(int n=0;n<colors.Length;n++)colors[n]=new Color(r.uvs[n].x,r.uvs[n].y,0,0);inputs.SetPixels(colors);inputs.Apply(false,false);
  try{foreach(var item in r.materials){
   if(File.Exists(item.raw_output))throw new Exception("Preserve prior output");var source=AssetDatabase.LoadAssetAtPath<Material>(AssetDatabase.GUIDToAssetPath(item.guid));if(source==null||Guid(source.shader)!="7dcd0e3bb8cbf2345a1e124f5a095198")throw new Exception("Source binding differs");string before=EditorJsonUtility.ToJson(source,true);var rows=new List<TextureRow>();
   foreach(string name in new[]{"_L1_Height","_L1_Albedo","_L1_Normal"}){var t=source.GetTexture(name) as Texture2D;if(t==null)throw new Exception("Texture missing");rows.Add(new TextureRow{property=name,guid=Guid(t),format=t.format.ToString(),graphics_format=t.graphicsFormat.ToString(),filter=t.filterMode.ToString(),wrap_u=t.wrapModeU.ToString(),wrap_v=t.wrapModeV.ToString(),width=t.width,height=t.height,mips=t.mipmapCount,aniso=t.anisoLevel});}
   var probe=new Material(shader);probe.CopyPropertiesFromMaterial(source);probe.SetTexture("_ProbeUvs",inputs);var rt=new RenderTexture(r.uvs.Length,9,0,RenderTextureFormat.ARGBFloat,RenderTextureReadWrite.Linear);rt.Create();var active=RenderTexture.active;var pixels=new Texture2D(r.uvs.Length,9,TextureFormat.RGBAFloat,false,true);
   try{Graphics.SetRenderTarget(rt);GL.Clear(false,true,Color.clear);if(!probe.SetPass(0))throw new Exception("Probe pass refused");Graphics.DrawProceduralNow(MeshTopology.Triangles,3,1);RenderTexture.active=rt;pixels.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0,false);pixels.Apply(false,false);var data=pixels.GetRawTextureData<byte>().ToArray();foreach(var v in pixels.GetPixels())if(float.IsNaN(v.r)||float.IsNaN(v.g)||float.IsNaN(v.b)||float.IsNaN(v.a)||float.IsInfinity(v.r)||float.IsInfinity(v.g)||float.IsInfinity(v.b)||float.IsInfinity(v.a))throw new Exception("Nonfinite probe result");File.WriteAllBytes(item.raw_output,data);if(before!=EditorJsonUtility.ToJson(source,true))throw new Exception("Source changed");result.Add(new Row{guid=item.guid,raw_output=item.raw_output,output_bytes=data.Length,textures=rows.ToArray(),source_material_unchanged=true});}
   finally{RenderTexture.active=active;rt.Release();UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(pixels);UnityEngine.Object.DestroyImmediate(probe);}
  }}finally{UnityEngine.Object.DestroyImmediate(inputs);}
  File.WriteAllText(r.output,JsonUtility.ToJson(new Report{unity_version=Application.unityVersion,graphics_api=SystemInfo.graphicsDeviceType.ToString(),gpu=SystemInfo.graphicsDeviceName,color_space=QualitySettings.activeColorSpace.ToString(),cases=r.uvs.Length,rows=9,materials=result.ToArray(),source_materials_unchanged=true},true));
 }
}
